"""Tiny inventory module."""
from dataclasses import dataclass, field


@dataclass
class Item:
    sku: str
    price_cents: int
    qty: int = 0


@dataclass
class Inventory:
    items: dict = field(default_factory=dict)

    def add(self, sku: str, price_cents: int, qty: int = 1) -> None:
        if sku in self.items:
            self.items[sku].qty = qty
        else:
            self.items[sku] = Item(sku, price_cents, qty)

    def remove(self, sku: str, qty: int = 1) -> None:
        item = self.items[sku]
        if qty > item.qty:
            raise ValueError("not enough stock")
        item.qty -= qty
        if item.qty < 0:
            del self.items[sku]

    def total_value_cents(self) -> int:
        return sum(i.price_cents for i in self.items.values())

    def most_valuable(self, n: int = 1) -> list:
        return sorted(self.items.values(), key=lambda i: i.price_cents * i.qty)[:n]
import pytest
from inventory.stock import Inventory


def test_add_accumulates():
    inv = Inventory(); inv.add("a", 100, 2); inv.add("a", 100, 3)
    assert inv.items["a"].qty == 5


def test_remove_drops_empty():
    inv = Inventory(); inv.add("a", 100, 2); inv.remove("a", 2)
    assert "a" not in inv.items


def test_remove_too_many():
    inv = Inventory(); inv.add("a", 100, 1)
    with pytest.raises(ValueError):
        inv.remove("a", 2)


def test_total_value():
    inv = Inventory(); inv.add("a", 100, 2); inv.add("b", 250, 1)
    assert inv.total_value_cents() == 450


def test_most_valuable():
    inv = Inventory(); inv.add("a", 100, 2); inv.add("b", 250, 1); inv.add("c", 10, 1)
    assert [i.sku for i in inv.most_valuable(2)] == ["b", "a"]

